-- Chạy trong database đã chọn bằng phpMyAdmin. Không xóa bảng NearLink hiện có.
CREATE TABLE IF NOT EXISTS eq_users (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(254) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  display_name VARCHAR(60) NOT NULL DEFAULT 'Nhà thám hiểm',
  auth_version INT UNSIGNED NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  UNIQUE KEY uq_eq_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS eq_password_resets (
  token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY,
  user_id BIGINT UNSIGNED NOT NULL,
  expires_at BIGINT UNSIGNED NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY idx_eq_reset_user (user_id),
  KEY idx_eq_reset_expiry (expires_at),
  CONSTRAINT fk_eq_reset_user FOREIGN KEY (user_id) REFERENCES eq_users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS eq_rate_limits (
  bucket CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL PRIMARY KEY,
  hits INT UNSIGNED NOT NULL,
  expires_at BIGINT UNSIGNED NOT NULL,
  KEY idx_eq_rate_expiry (expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Run after accounts.sql. Never imports client XP.
CREATE TABLE IF NOT EXISTS eq_progress (
 user_id BIGINT UNSIGNED PRIMARY KEY,
 state LONGTEXT NOT NULL,
 FOREIGN KEY (user_id) REFERENCES eq_users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eq_game_events (
 user_id BIGINT UNSIGNED NOT NULL,
 event_id VARCHAR(64) CHARACTER SET ascii NOT NULL,
 result TEXT NOT NULL,
 PRIMARY KEY(user_id,event_id),
 FOREIGN KEY (user_id) REFERENCES eq_users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS eqx_profiles (user_id BIGINT UNSIGNED PRIMARY KEY, username VARCHAR(40) UNIQUE, bio TEXT NOT NULL, level VARCHAR(2) NOT NULL, goal VARCHAR(160) NOT NULL, minutes INTEGER NOT NULL DEFAULT 10, discover INTEGER NOT NULL DEFAULT 1, online_visible INTEGER NOT NULL DEFAULT 0, location_enabled INTEGER NOT NULL DEFAULT 0, lat DECIMAL(8,2) NULL, lng DECIMAL(8,2) NULL, avatar_id BIGINT UNSIGNED NULL, cover_id BIGINT UNSIGNED NULL, role VARCHAR(16) NOT NULL DEFAULT 'user', suspended INTEGER NOT NULL DEFAULT 0, verified_email VARCHAR(254) NULL, last_seen BIGINT UNSIGNED NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_sessions (token VARCHAR(64) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, created_at BIGINT UNSIGNED NOT NULL, seen_at BIGINT UNSIGNED NOT NULL, revoked INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_friends (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, low_id BIGINT UNSIGNED NOT NULL, high_id BIGINT UNSIGNED NOT NULL, requester_id BIGINT UNSIGNED NOT NULL, status VARCHAR(16) NOT NULL, UNIQUE(low_id,high_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_blocks (user_id BIGINT UNSIGNED NOT NULL, target_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,target_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_follows (user_id BIGINT UNSIGNED NOT NULL, target_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,target_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_groups (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, level VARCHAR(16) NOT NULL, description TEXT NOT NULL, created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_group_members (group_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(group_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_posts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, visibility VARCHAR(16) NOT NULL, group_id BIGINT UNSIGNED NULL, file_id BIGINT UNSIGNED NULL, category VARCHAR(16) NOT NULL DEFAULT 'post', transcript TEXT NULL, deleted INTEGER NOT NULL DEFAULT 0, created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_comments (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, post_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, parent_id BIGINT UNSIGNED NULL, body TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0, created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_reactions (user_id BIGINT UNSIGNED NOT NULL, post_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(8) NOT NULL, PRIMARY KEY(user_id,post_id,kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_rooms (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, kind VARCHAR(16) NOT NULL, pair_key VARCHAR(60) NULL UNIQUE, created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_room_members (room_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, read_id BIGINT UNSIGNED NOT NULL DEFAULT 0, delivered_id BIGINT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(room_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, room_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, body TEXT NOT NULL, file_id BIGINT UNSIGNED NULL, reply_id BIGINT UNSIGNED NULL, client_key VARCHAR(64) NOT NULL, recalled INTEGER NOT NULL DEFAULT 0, edited INTEGER NOT NULL DEFAULT 0, created_at BIGINT UNSIGNED NOT NULL, UNIQUE(user_id,client_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_notifications (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, actor_id BIGINT UNSIGNED NOT NULL, body VARCHAR(255) NOT NULL, ref_type VARCHAR(16) NOT NULL, ref_id BIGINT UNSIGNED NOT NULL, seen INTEGER NOT NULL DEFAULT 0, created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_folders (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, name VARCHAR(160) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_files (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, folder_id BIGINT UNSIGNED NULL, name VARCHAR(180) NOT NULL, stored VARCHAR(100) NOT NULL, mime VARCHAR(80) NOT NULL, bytes BIGINT UNSIGNED NOT NULL, deleted INTEGER NOT NULL DEFAULT 0, created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_file_grants (file_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(file_id,user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_reports (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, target_type VARCHAR(16) NOT NULL, target_id BIGINT UNSIGNED NOT NULL, reason TEXT NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'open', created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_orders (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, plan VARCHAR(8) NOT NULL, amount BIGINT UNSIGNED NOT NULL, currency VARCHAR(3) NOT NULL, status VARCHAR(16) NOT NULL, reference VARCHAR(160) NULL, created_at BIGINT UNSIGNED NOT NULL, paid_at BIGINT UNSIGNED NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_subscriptions (user_id BIGINT UNSIGNED PRIMARY KEY, plan VARCHAR(8) NOT NULL, expires_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_payment_receipts (reference VARCHAR(160) PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_ai_usage (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, task VARCHAR(24) NOT NULL, day VARCHAR(10) NOT NULL, status VARCHAR(20) NOT NULL, created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_support (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, game VARCHAR(32) NOT NULL, run_id VARCHAR(40) NULL, question TEXT NOT NULL, answer TEXT NOT NULL, source VARCHAR(16) NOT NULL, created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_assistant_preferences (user_id BIGINT UNSIGNED PRIMARY KEY, language VARCHAR(2) NOT NULL, mode VARCHAR(16) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_runs (id VARCHAR(40) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, game VARCHAR(32) NOT NULL, state LONGTEXT NOT NULL, started_at BIGINT UNSIGNED NOT NULL, updated_at BIGINT UNSIGNED NOT NULL, finished INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_rewards (run_id VARCHAR(40) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, day VARCHAR(10) NOT NULL, xp INTEGER NOT NULL, coins INTEGER NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_wallets (user_id BIGINT UNSIGNED PRIMARY KEY, coins INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_speaking (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, sample TEXT NOT NULL, transcript TEXT NOT NULL, created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_email_tokens (token VARCHAR(64) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, email VARCHAR(254) NOT NULL, expires_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_audit (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NOT NULL, action VARCHAR(40) NOT NULL, target_id BIGINT UNSIGNED NOT NULL, detail TEXT NOT NULL, created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqx_migrations (version VARCHAR(30) PRIMARY KEY, applied_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
