-- Additive upgrade; choose existing English Quest database first. Back up before import.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS eq_auth_accounts (user_id BIGINT UNSIGNED PRIMARY KEY,status VARCHAR(16) NOT NULL,verified_email VARCHAR(254) NULL,email_verified_at BIGINT UNSIGNED NULL,legacy_access INTEGER NOT NULL DEFAULT 0,created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eq_auth_tokens (token_hash VARCHAR(64) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,email VARCHAR(254) NOT NULL,purpose VARCHAR(12) NOT NULL,expires_at BIGINT UNSIGNED NOT NULL,used_at BIGINT UNSIGNED NULL,created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eq_auth_security (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,event VARCHAR(40) NOT NULL,ip_hash VARCHAR(64) NOT NULL,email_hash VARCHAR(64) NULL,created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqd_settings (user_id BIGINT UNSIGNED PRIMARY KEY,allow_email_search INTEGER NOT NULL DEFAULT 0,country VARCHAR(2) NOT NULL DEFAULT '',city VARCHAR(120) NOT NULL DEFAULT '',language VARCHAR(80) NOT NULL DEFAULT 'vi',timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Ho_Chi_Minh',study_window VARCHAR(30) NOT NULL DEFAULT 'evening',interests VARCHAR(240) NOT NULL DEFAULT '',seeking INTEGER NOT NULL DEFAULT 1,show_region INTEGER NOT NULL DEFAULT 0,age_band VARCHAR(12) NOT NULL DEFAULT 'unspecified',message_policy VARCHAR(12) NOT NULL DEFAULT 'friends',location_enabled INTEGER NOT NULL DEFAULT 0,share_achievements INTEGER NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqd_locations (user_id BIGINT UNSIGNED PRIMARY KEY,lat DECIMAL(5,2) NOT NULL,lng DECIMAL(6,2) NOT NULL,updated_at BIGINT UNSIGNED NOT NULL,expires_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqd_invitations (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,sender_id BIGINT UNSIGNED NOT NULL,recipient_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(16) NOT NULL,title VARCHAR(160) NOT NULL,notes TEXT NOT NULL,course_id VARCHAR(60) NULL,starts_at BIGINT UNSIGNED NULL,status VARCHAR(16) NOT NULL DEFAULT 'pending',room_id BIGINT UNSIGNED NULL,created_at BIGINT UNSIGNED NOT NULL,updated_at BIGINT UNSIGNED NOT NULL,client_key VARCHAR(64) NOT NULL,UNIQUE(sender_id,client_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqd_challenges (invite_id BIGINT UNSIGNED PRIMARY KEY,game VARCHAR(16) NOT NULL,sender_run VARCHAR(40) NOT NULL,recipient_run VARCHAR(40) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqc_courses (id VARCHAR(60) PRIMARY KEY,title VARCHAR(160) NOT NULL,description TEXT NOT NULL,level VARCHAR(16) NOT NULL,language_code VARCHAR(16) NOT NULL DEFAULT 'en-US',skill VARCHAR(30) NOT NULL,published INTEGER NOT NULL DEFAULT 0,position INTEGER NOT NULL DEFAULT 1,version INTEGER NOT NULL DEFAULT 1,final_json LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqc_units (id VARCHAR(60) PRIMARY KEY,course_id VARCHAR(60) NOT NULL,title VARCHAR(160) NOT NULL,position INTEGER NOT NULL,published INTEGER NOT NULL DEFAULT 1,exam_json LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqc_lessons (id VARCHAR(60) PRIMARY KEY,unit_id VARCHAR(60) NOT NULL,title VARCHAR(160) NOT NULL,position INTEGER NOT NULL,published INTEGER NOT NULL DEFAULT 1,content_json LONGTEXT NOT NULL,exercises_json LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqc_progress (user_id BIGINT UNSIGNED NOT NULL,target_id VARCHAR(60) NOT NULL,kind VARCHAR(12) NOT NULL,score INTEGER NOT NULL DEFAULT 0,total INTEGER NOT NULL DEFAULT 0,passed INTEGER NOT NULL DEFAULT 0,completed_at BIGINT UNSIGNED NULL,PRIMARY KEY(user_id,target_id,kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqc_runs (id VARCHAR(40) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,course_id VARCHAR(60) NOT NULL,target_id VARCHAR(60) NOT NULL,kind VARCHAR(12) NOT NULL,state LONGTEXT NOT NULL,finished INTEGER NOT NULL DEFAULT 0,started_at BIGINT UNSIGNED NOT NULL,updated_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqc_certificates (id VARCHAR(40) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,course_id VARCHAR(60) NOT NULL,course_title VARCHAR(160) NOT NULL,display_name VARCHAR(60) NOT NULL,score INTEGER NOT NULL,issued_at BIGINT UNSIGNED NOT NULL,UNIQUE(user_id,course_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqc_media (lesson_id VARCHAR(60) NOT NULL,file_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(lesson_id,file_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqc_reviews (user_id BIGINT UNSIGNED NOT NULL,lesson_id VARCHAR(60) NOT NULL,word_index INTEGER NOT NULL,due_at BIGINT UNSIGNED NOT NULL,interval_days INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,lesson_id,word_index)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
