INSERT INTO eq_auth_accounts(user_id,status,legacy_access,created_at) SELECT u.id,'active',1,UNIX_TIMESTAMP() FROM eq_users u WHERE NOT EXISTS(SELECT 1 FROM eq_auth_accounts a WHERE a.user_id=u.id);
UPDATE eqx_profiles SET lat=NULL,lng=NULL,location_enabled=0; -- Retire legacy location storage; new consent is separate.
