-- SPA/Profile/Speaking additive upgrade, after the existing upgrade migration.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS eqp_email_changes (user_id BIGINT UNSIGNED PRIMARY KEY,email VARCHAR(254) NOT NULL,old_email VARCHAR(254) NOT NULL,auth_version INTEGER NOT NULL,created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqs_practice_sessions (id VARCHAR(40) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,task_key VARCHAR(100) NOT NULL,payload LONGTEXT NOT NULL,started_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqs_attempts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,session_id VARCHAR(40) NOT NULL UNIQUE,legacy_id BIGINT UNSIGNED NOT NULL,mode VARCHAR(16) NOT NULL,level VARCHAR(2) NOT NULL,topic VARCHAR(100) NOT NULL,content_match INTEGER NOT NULL,result_json LONGTEXT NOT NULL,record_file_id BIGINT UNSIGNED NULL,record_consent INTEGER NOT NULL DEFAULT 0,created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqs_rewards (user_id BIGINT UNSIGNED NOT NULL,day VARCHAR(10) NOT NULL,task_key VARCHAR(100) NOT NULL,xp INTEGER NOT NULL,PRIMARY KEY(user_id,day,task_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqs_conversations (id VARCHAR(40) PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,topic VARCHAR(60) NOT NULL,level VARCHAR(2) NOT NULL,created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eqs_turns (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,conversation_id VARCHAR(40) NOT NULL,client_key VARCHAR(64) NOT NULL,question TEXT NOT NULL,answer TEXT NULL,source VARCHAR(16) NOT NULL DEFAULT 'pending',status VARCHAR(16) NOT NULL DEFAULT 'pending',created_at BIGINT UNSIGNED NOT NULL,UNIQUE(conversation_id,client_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
SET @eq_sql=IF(EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='eqs_practice_sessions' AND index_name='eqs_practice_user'),'SELECT 1','CREATE INDEX eqs_practice_user ON eqs_practice_sessions(user_id,started_at)');
PREPARE eq_stmt FROM @eq_sql; EXECUTE eq_stmt; DEALLOCATE PREPARE eq_stmt;
SET @eq_sql=IF(EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='eqs_attempts' AND index_name='eqs_attempts_user'),'SELECT 1','CREATE INDEX eqs_attempts_user ON eqs_attempts(user_id,id)');
PREPARE eq_stmt FROM @eq_sql; EXECUTE eq_stmt; DEALLOCATE PREPARE eq_stmt;
SET @eq_sql=IF(EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='eqs_conversations' AND index_name='eqs_conversations_user'),'SELECT 1','CREATE INDEX eqs_conversations_user ON eqs_conversations(user_id,created_at)');
PREPARE eq_stmt FROM @eq_sql; EXECUTE eq_stmt; DEALLOCATE PREPARE eq_stmt;
SET @eq_sql=IF(EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='eqs_turns' AND index_name='eqs_turns_conversation'),'SELECT 1','CREATE INDEX eqs_turns_conversation ON eqs_turns(conversation_id,id)');
PREPARE eq_stmt FROM @eq_sql; EXECUTE eq_stmt; DEALLOCATE PREPARE eq_stmt;
